import difflib

abbreviations = {
    'hn': 'hijo natural',
    'hl': 'hijo legitimo',
    'id': 'indigena'
}

facets = {
    "Ethno-Racial Category": set(),
    "Legitimacy Status": set(),
    "Geographic Location": set()
}

for cluster in clusters:
    words = cluster.split(',')
    for word in words:
        normalized_word = difflib.get_close_matches(word, list(abbreviations.values()), n=1, cutoff=0.8)[0]
        if normalized_word not in facets["Ethno-Racial Category"]:
            facets["Ethno-Racial Category"].add(normalized_word)
        if word in abbreviations.keys():
            facets["Legitimacy Status"].add(abbreviations[word])
        if 'aucara' not in normalized_word and 'punas' not in normalized_word:
            facets["Geographic Location"].add(normalized_word)

result = {facet: list(sorted(value)) for facet, value in facets.items()}
